using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
[DefaultExecutionOrder(2800)]public sealed class MesaMoodV12:MonoBehaviour {
 public SteamJourney journey;public Renderer[] workshopFloor;bool applied;bool[] saved;float distance;
 void LateUpdate(){if(!journey)return;var p=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;if(!journey.inSandbox){if(applied){if(p)p.shadowDistance=distance;if(workshopFloor!=null)for(int k=0;k<workshopFloor.Length;k++)if(workshopFloor[k])workshopFloor[k].enabled=saved[k];}applied=false;return;}if(applied)return;applied=true;if(p){distance=p.shadowDistance;p.shadowDistance=80;}if(workshopFloor!=null){saved=new bool[workshopFloor.Length];for(int k=0;k<workshopFloor.Length;k++)if(workshopFloor[k]){saved[k]=workshopFloor[k].enabled;workshopFloor[k].enabled=false;}}Apply(journey);}
 public static void Apply(SteamJourney j){Shader.SetGlobalFloat("GrassRenderDist",90);Shader.SetGlobalFloat("WindPower",.035f);Shader.SetGlobalFloat("WindSpeed",.45f);Shader.SetGlobalFloat("WindBurstsPower",.05f);Shader.SetGlobalFloat("MicroPower",.008f);Shader.SetGlobalFloat("MicroSpeed",.65f);Shader.SetGlobalFloat("MicroFrequency",3);var m=Object.FindObjectOfType<StudioWorkshopMood>();if(m){m.key.intensity=1.6f;m.key.color=new Color(1,.88f,.75f);m.key.transform.rotation=Quaternion.Euler(38,-42,0);m.fill.intensity=.30f;m.fill.color=new Color(.65f,.78f,1);m.fill.transform.rotation=Quaternion.Euler(42,120,0);m.rim.intensity=.35f;m.rim.color=new Color(.82f,.90f,1);m.rim.transform.rotation=Quaternion.Euler(25,200,0);}RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.35f,.43f,.53f);RenderSettings.ambientEquatorColor=new Color(.23f,.23f,.24f);RenderSettings.ambientGroundColor=new Color(.13f,.105f,.08f);RenderSettings.reflectionIntensity=.7f;RenderSettings.fog=false;j.view.backgroundColor=new Color(.055f,.072f,.085f);}
}

